def build_ibt_choose_responses(pack_num: int) -> list[dict]:
    """Builds 15 'Listen and Choose a Response' items (Q051..Q065) for pack 1..5."""
    items = []
    q_idx = 51
    entries = _RESP[pack_num]
    assert len(entries) == 15, f"Pack {pack_num} iBT choose responses count {len(entries)} != 15"
    for idx, (tag, spk, line, opts, cidx, mod, diff, exp) in enumerate(entries, start=1):
        qid = f"IBT26-0{pack_num}-Q{q_idx:03d}"
        aid = f"IBT0{pack_num}-LR{idx:02d}"
        prompt = f"Listen and Choose a Response — Prompt {idx}/15 ({tag}): Select the most natural reply."
        items.append(
            rotated_mcq(
                qid=qid,
                section="LISTENING",
                prompt=prompt,
                options=opts,
                correct_idx=cidx,
                explanation=exp,
                rationale_source=mod,
                difficulty=diff,
                seed=pack_num * 23 + idx,
                audio_id=aid,
                audio_turns=[(spk, line)],
            ),
        )
        q_idx += 1
    return items
